var ITEMS=[["Copa America: overview","The Copa America is South American's soccer competition, founded 1916 with 16 teams."], ["league","Copa America"], ["sport","soccer"], ["region","South American"], ["founded","1916"]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
